result = [4, 4, 0, 4, 1, 4, 3, 3, 3, 2, 2, 4, 4, 3, 1, 0, 2, 1, 0]
# Check the sums
subsets = {0: [], 1: [], 2: [], 3: [], 4: []}
for i, subset_id in enumerate(result):
    subsets[subset_id].append(i + 1)

print("Subsets:", subsets)
for s in range(5):
    print(f"Sum of subset {s}: {sum(subsets[s])}")
